def gen(rng):
    LIM = 10 ** 9
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    def make(m, lo=-LIM, hi=LIM):
        vals = rng.sample(range(lo, hi + 1), m + 1)
        a = vals[:m] * 2 + [vals[m]]
        rng.shuffle(a)
        return a
    tests = [fmt([0 + 5]), fmt([-7]), fmt([0]), fmt([LIM]), fmt([-LIM]), fmt([2, 2, 1]), fmt([1, 2, 2]),
             fmt([0, 0, -LIM]), fmt([4, 1, 2, 1, 2]), fmt([LIM, -LIM, LIM])]
    for _ in range(40):
        m = rng.randint(0, 8)
        tests.append(fmt(make(m, -12, 12) if m <= 12 else make(m)))
    for _ in range(4):
        tests.append(fmt(make(rng.randint(30, 60))))
    tests.append(fmt(make(15000)))
    tests.append(fmt(make(15000, -LIM, -LIM + 40000)))
    tests.append(fmt(make(15000, LIM - 40000, LIM)))
    return tests
